"""Codex protocol fixtures follow schemas generated by the installed CLI."""
import importlib.util
from pathlib import Path
from types import SimpleNamespace

import pytest

ROOT=Path(__file__).resolve().parents[1]
PATH=ROOT/'skills/plugin-panel/scripts/console_codex.py'

def api():
    assert PATH.is_file(), 'Codex console adapter is not implemented'
    spec=importlib.util.spec_from_file_location('tested_console_codex',PATH)
    module=importlib.util.module_from_spec(spec);spec.loader.exec_module(module);return module

class Peer:
    def __init__(self,argv,cwd,receive,on_exit=None):
        self.cwd,self.receive=cwd,receive;self.calls=[];self.sent=[];self.closed=False;self.foreign=False
    def start(self):pass
    def call(self,method,params,timeout=15):
        self.calls.append((method,params))
        thread={'id':'thread-one','cwd':str(self.cwd/'other' if self.foreign else self.cwd),'status':{'type':'idle'}}
        if method in ('thread/start','thread/read','thread/resume'):return {'thread':thread}
        if method=='turn/start':return {'turn':{'id':'turn-one'}}
        if method=='thread/items/list':return {'data':[],'nextCursor':None}
        return {}
    def send(self,value):self.sent.append(value)
    def close(self):self.closed=True

def driver(tmp_path):
    out=[];d=api().Driver(SimpleNamespace(root=tmp_path,id='one'),out.append,peer_factory=Peer,command=['fake-native'])
    return d,out

def test_start_and_chat_use_project_scoped_rpc_without_permission_overrides(tmp_path):
    d,out=driver(tmp_path)
    assert d.start()=='thread-one'
    d.send('do the task & keep this as text')
    calls=dict(d.peer.calls)
    assert calls['thread/start']=={'cwd':str(tmp_path)}
    assert calls['turn/start']['input']==[{'type':'text','text':'do the task & keep this as text'}]
    assert not any('approvalPolicy' in p or 'sandbox' in p for _,p in d.peer.calls)


def test_fast_native_completion_is_not_overwritten_by_turn_start_ack(tmp_path):
    d,out=driver(tmp_path);d.start();original=d.peer.call
    def fast(method,params,timeout=15):
        if method=='turn/start':
            d.handle({'method':'turn/started','params':{'threadId':'thread-one','turn':{'id':'turn-fast'}}})
            d.handle({'method':'turn/completed','params':{'threadId':'thread-one','turn':{'id':'turn-fast','status':'completed'}}})
            return {'turn':{'id':'turn-fast'}}
        return original(method,params,timeout)
    d.peer.call=fast;out.clear();d.send('quick reply')
    assert out[-1]['status']=='idle'
    assert d.turn_id is None

def test_resume_rejects_foreign_directory_before_resuming_or_reading_history(tmp_path):
    d,out=driver(tmp_path)
    d.peer=Peer([],tmp_path,d.handle);d.peer.foreign=True
    with pytest.raises(ValueError):d.start('thread-one')
    assert 'thread/resume' not in [name for name,_ in d.peer.calls]
    assert 'thread/items/list' not in [name for name,_ in d.peer.calls]

def test_native_events_filter_thread_and_never_emit_reasoning(tmp_path):
    d,out=driver(tmp_path);d.start();out.clear()
    d.handle({'method':'item/agentMessage/delta','params':{'threadId':'other','itemId':'x','delta':'foreign'}})
    d.handle({'method':'item/reasoning/textDelta','params':{'threadId':'thread-one','delta':'private thought'}})
    assert out==[]
    d.handle({'method':'item/agentMessage/delta','params':{'threadId':'thread-one','itemId':'x','delta':'visible'}})
    d.handle({'method':'turn/completed','params':{'threadId':'thread-one','turn':{'id':'turn-one','status':'failed'}}})
    assert out[0]=={'type':'message','id':'x','role':'assistant','text':'visible','delta':True}
    assert out[-1]['status']=='failed'

def test_approval_response_uses_the_original_request_and_rejects_unknown_decisions(tmp_path):
    d,out=driver(tmp_path);d.start();out.clear()
    d.handle({'id':91,'method':'item/commandExecution/requestApproval','params':{'threadId':'thread-one','command':'git status','availableDecisions':['accept','decline','cancel']}})
    assert out[-1]['type']=='approval' and out[-1]['choices']==['allow','deny','cancel']
    with pytest.raises(ValueError):d.answer('91',{'decision':'bypass'})
    d.answer('91',{'decision':'deny'})
    assert d.peer.sent[-1]=={'id':91,'result':{'decision':'decline'}}

def test_interrupt_is_a_request_until_turn_completion_arrives(tmp_path):
    d,out=driver(tmp_path);d.start();d.send('hello');out.clear();d.interrupt()
    assert d.peer.calls[-1]==('turn/interrupt',{'threadId':'thread-one','turnId':'turn-one'})
    assert not any(e.get('status')=='interrupted' for e in out)
    d.handle({'method':'turn/completed','params':{'threadId':'thread-one','turn':{'id':'turn-one','status':'interrupted'}}})
    assert out[-1]['status']=='interrupted'


def test_an_explicit_empty_native_decision_list_does_not_invent_permission(tmp_path):
    d,out=driver(tmp_path);d.start();out.clear()
    d.handle({'id':92,'method':'item/commandExecution/requestApproval','params':{
        'threadId':'thread-one','command':'native-only operation','availableDecisions':[]}})
    assert out[-1]['choices']==[]
    with pytest.raises(ValueError):d.answer('92',{'decision':'allow'})
    assert d.peer.sent[-1].get('id')!=92

@pytest.mark.skipif(__import__('os').name!='nt',reason='Windows path contract')
def test_native_extended_windows_path_resolves_to_the_same_project(tmp_path):
    d,out=driver(tmp_path)
    d._scope({'cwd':chr(92)*2+'?'+chr(92)+str(tmp_path)})
